      bfxAnimate(bolt, [{ opacity: 0 }, { opacity: 0, offset: .2 }, { opacity: 1, offset: .21 }, { opacity: 0, offset: .24 }, { opacity: 1, offset: .26 }, { opacity: 0, offset: .31 }, { opacity: 0 }], { duration: D, easing: 'linear' });
