      document.getElementById('seriesModalText').innerHTML = `<b>${escapeHtml(seriesOtherName(s))}</b> challenges you to a Best of ${s.bestOf}. First to ${s.need} wins.`;
      document.getElementById('seriesModalPot').innerHTML = `<span><b>${s.fee} ${gem}</b>Entry</span><span><b>${s.pot} ${gem}</b>Winner takes</span>`;
      document.getElementById('seriesModalStatus').classList.add('hidden');
