      const recorded = !!(seriesState.games?.[state.matchId] || seriesState.skippedGames?.[state.matchId]);
      const label = !recorded ? 'CONFIRMING RESULT…' : seriesReadyBusy ? 'SAVING READY…' : both ? 'STARTING NEXT GAME…' : mine ? 'READY · WAITING FOR OPPONENT' : 'READY FOR NEXT GAME';
