      try {
        const snap = await db.ref(`users/${uid}/activityInbox`).orderByKey().startAt('series_').endAt('series_\uf8ff').limitToLast(5).once('value');
        const mails = Object.entries(snap.val() || {}).map(([k, m]) => ({ ...m, id: k.replace(/^series_/, '') }))
          .filter(m => m && m.type === 'series' && Date.now() - (Number(m.sentAt) || 0) < 24 * 3600 * 1000 && !seriesResultSeen(m.id))
          .sort((a, b) => (b.sentAt || 0) - (a.sentAt || 0));
        if (mails.length && !state.isMultiplayer) showSeriesResultPopup(mails[0]);
      } catch (_) {}
