    // buttons if that auto-start somehow doesn't fire.
    document.getElementById('rankedConnectedLeaveBtn').addEventListener('click', () => {
      forgetJoinedRoom();
      location.reload();
    });


    document.getElementById('setIconsRow').addEventListener('click', () => {
      showCardIcons = !showCardIcons;
      try { localStorage.setItem('shithead_card_icons', showCardIcons ? '1' : '0'); } catch (e) {}
      refreshSettingsUI(); render(); scheduleSettingsCloudSave();
    });
    document.getElementById('setRankRow').addEventListener('click', () => {
      const newValue = !selectAllOfRank;
      if (!newValue && !tutorialAllowToggleOff()) return;
      selectAllOfRank = newValue;
      state.selectedPlayCardIds = [];
      updateMultiSelectToggleUI(); refreshSettingsUI(); render(); scheduleSettingsCloudSave();
    });
    document.getElementById('setDoubleTapRow').addEventListener('click', () => {
      doubleTapPlay = !doubleTapPlay; writePref('shithead_double_tap_play', doubleTapPlay);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setProtectBestRow').addEventListener('click', () => {
      protectBestCards = !protectBestCards; writePref('shithead_protect_best', protectBestCards);
      state.selectedPlayCardIds = [];
      refreshSettingsUI(); scheduleSettingsCloudSave();
      if (state.phase && state.phase !== 'LOBBY') render();
    });
    document.getElementById('setFullscreenRow').addEventListener('click', () => {
      toggleFullscreen();
      setTimeout(refreshSettingsUI, 120);
    });
    // Collapsible sections. Chevron rotates to show state; sections start open.
    document.querySelectorAll('.settings-head').forEach(head => {
      head.addEventListener('click', () => {
        const body = document.getElementById(head.dataset.target);
        const chev = head.querySelector('.settings-chev');
        if (!body) return;
        const open = !body.classList.toggle('hidden');
        if (chev) chev.style.transform = open ? '' : 'rotate(-90deg)';
      });
    });

    // Settings search: matches each item's own visible text OR its
    // data-keywords (synonyms an item's own label would never contain —
    // e.g. "vfx" matching both Burn & Victory Effects and Shuffle & Deal
    // Animation). Scoped to #settingsModal specifically because
    // .settings-head is also reused outside it (the lobby's deck-theme
    // picker) — querying unscoped would drag an unrelated element into
    // this logic.
    document.getElementById('settingsSearchInput').addEventListener('input', (e) => {
      const q = e.target.value.trim().toLowerCase();
      const sectionsWithMatch = new Set();
      let anyVisible = false;
      document.querySelectorAll('#settingsModal .settings-searchable').forEach((item) => {
        const haystack = (item.textContent + ' ' + (item.dataset.keywords || '')).toLowerCase();
        const match = !q || haystack.includes(q);
        item.classList.toggle('hidden', !match);
        if (match) {
          anyVisible = true;
          const body = item.closest('.settings-body');
          if (body) sectionsWithMatch.add(body.id);
        }
      });
      // Searching looks across every tab; clearing it goes back to the tab.
      settingsSearching = !!q;
      document.querySelectorAll('#settingsModal .settings-tab-panel').forEach((panel) => {
        panel.classList.toggle('hidden', q ? !sectionsWithMatch.has(panel.id) : panel.dataset.settingsPanel !== settingsTab);
      });
      renderSettingsTabs();
      document.getElementById('settingsNoResultsMsg').classList.toggle('hidden', anyVisible || !q);
    });

    // Settings tabs: the same strip as the Shop and Custom pages.
    // § Settings page
    const SETTINGS_TABS = [
      { key: 'gameplay', label: 'Gameplay' },
      { key: 'display', label: 'Display' },
      { key: 'sound', label: 'Sound & Alerts' },
      { key: 'access', label: 'Accessibility' }
    ];
    let settingsTab = (() => {
      try { const t = localStorage.getItem('shithead_settings_tab'); return SETTINGS_TABS.some(x => x.key === t) ? t : 'gameplay'; } catch (e) { return 'gameplay'; }
    })();
    let settingsSearching = false;
    function renderSettingsTabs() {
      const bar = document.getElementById('settingsTabBar');
      if (!bar) return;
      bar.innerHTML = SETTINGS_TABS.map(t => `<button type="button" role="tab" class="cosmetic-tab" data-settings-tab="${t.key}" aria-selected="${!settingsSearching && t.key === settingsTab}">${t.label}</button>`).join('');
      initHorizontalScroller(bar);
    }
    function showSettingsTab(key) {
      if (!SETTINGS_TABS.some(t => t.key === key)) return;
      settingsTab = key;
      try { localStorage.setItem('shithead_settings_tab', key); } catch (e) {}
      const search = document.getElementById('settingsSearchInput');
      if (search && search.value) { search.value = ''; search.dispatchEvent(new Event('input')); }
      settingsSearching = false;
      document.querySelectorAll('#settingsModal .settings-tab-panel').forEach((panel) => {
        panel.classList.toggle('hidden', panel.dataset.settingsPanel !== key);
      });
      document.getElementById('settingsScroll')?.scrollTo(0, 0);
      renderSettingsTabs();
    }
    document.getElementById('settingsTabBar')?.addEventListener('click', (e) => {
      const tab = e.target.closest('[data-settings-tab]');
      if (tab) showSettingsTab(tab.dataset.settingsTab);
    });
    showSettingsTab(settingsTab);

    // Mute remembers the previous level so unmuting restores it rather than
    // jumping to some arbitrary default.
    let volumeBeforeMute = masterVolume || 85;
    function refreshMuteBtn() {
      const btn = document.getElementById('muteBtn');
      if (!btn) return;
      const on = masterVolume > 0;
      btn.textContent = on ? 'ON' : 'MUTE';
      btn.className = `text-[10px] font-black px-2 py-0.5 rounded border ${on
        ? 'text-emerald-400 border-emerald-500' : 'text-rose-400 border-rose-500'}`;
    }
    document.getElementById('muteBtn').addEventListener('click', () => {
      if (masterVolume > 0) { volumeBeforeMute = masterVolume; masterVolume = 0; }
      else { masterVolume = volumeBeforeMute || 85; }
      try { localStorage.setItem('shithead_volume', String(masterVolume)); } catch (e) {}
      applyAccessibilityPrefs(); refreshSettingsUI(); scheduleSettingsCloudSave();
    });

    document.getElementById('speedResetBtn').addEventListener('click', () => {
      const slider = document.getElementById('headerSpeedSlider');
      slider.value = DEFAULT_SPEED_INDEX;
      slider.dispatchEvent(new Event('input'));
    });

    // Big Print Cards (Accessibility) equips the free Big Print deck; turning
    // it off puts back the deck worn before (shithead_deck_before_bigprint).
    document.getElementById('setBigPrintRow').addEventListener('click', () => {
      if (state.deckTheme === 'theme-bigprint') {
        let back = 'theme-obsidian';
        try { back = localStorage.getItem('shithead_deck_before_bigprint') || back; } catch (e) {}
        selectDeckTheme(back === 'theme-bigprint' ? 'theme-obsidian' : back);
      } else {
        try { localStorage.setItem('shithead_deck_before_bigprint', state.deckTheme || 'theme-obsidian'); } catch (e) {}
        selectDeckTheme('theme-bigprint');
      }
      refreshSettingsUI();
    });
    document.getElementById('setContrastRow').addEventListener('click', () => {
      highContrast = !highContrast; writePref('shithead_high_contrast', highContrast);
      applyAccessibilityPrefs(); refreshSettingsUI(); render(); scheduleSettingsCloudSave();
    });
    document.getElementById('setHideHelpersRow').addEventListener('click', () => {
      hideHelperIcons = !hideHelperIcons; writePref('shithead_hide_helpers', hideHelperIcons);
      applyAccessibilityPrefs(); refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setHelperTipsRow').addEventListener('click', () => {
      helperTipsOn = !helperTipsOn; writePref('shithead_helper_tips', helperTipsOn);
      if (!helperTipsOn) hideHelperTip();
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setMotionRow').addEventListener('click', () => {
      reduceMotion = !reduceMotion; writePref('shithead_reduce_motion', reduceMotion);
      applyAccessibilityPrefs(); refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setBigEffectsRow').addEventListener('click', () => {
      bigEffectsOn = !bigEffectsOn; writePref('shithead_big_effects', bigEffectsOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setHistoryRow').addEventListener('click', () => {
      historyOpenPref = !historyOpenPref; writePref('shithead_history_open', historyOpenPref);
      setHistoryOpen(historyOpenPref);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setOthersEffectsRow').addEventListener('click', () => {
      othersEffectsOn = !othersEffectsOn; writePref('shithead_others_effects', othersEffectsOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setHapticsRow').addEventListener('click', () => {
      hapticsOn = !hapticsOn; writePref('shithead_haptics', hapticsOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setTurnAlertRow').addEventListener('click', () => {
      turnAlertOn = !turnAlertOn; writePref('shithead_turn_alert', turnAlertOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
      if (turnAlertOn) audio.playTurnAlert(); // a preview of what it sounds like
    });
    document.getElementById('setNotifySoundRow').addEventListener('click', () => {
      notifySoundOn = !notifySoundOn; writePref('shithead_notify_sound', notifySoundOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
      if (notifySoundOn) audio.playNotify();
    });
    document.getElementById('setDealAnimRow').addEventListener('click', () => {
      dealAnimationOn = !dealAnimationOn; writePref('shithead_deal_animation', dealAnimationOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setLiveWatchRow').addEventListener('click', () => {
      liveWatchOn = !liveWatchOn; writePref('shithead_live_watch', liveWatchOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
      syncPlayingStatus(); scheduleLiveGame();
    });
    document.getElementById('setWhatsNewRow').addEventListener('click', () => {
      whatsNewOn = !whatsNewOn; writePref('shithead_whats_new', whatsNewOn);
      refreshSettingsUI(); scheduleSettingsCloudSave();
    });
    document.getElementById('setHandSortRow').addEventListener('click', () => {
      handSortByPower = !handSortByPower; writePref('shithead_hand_sort_power', handSortByPower);
      refreshSettingsUI(); scheduleSettingsCloudSave();
      if (state.phase && state.phase !== 'LOBBY') render();
    });
    document.getElementById('volumeSlider').addEventListener('input', (e) => {
      masterVolume = parseInt(e.target.value, 10);
      try { localStorage.setItem('shithead_volume', String(masterVolume)); } catch (err) {}
      document.getElementById('volumeLabel').textContent = `${masterVolume}%`;
      applyAccessibilityPrefs();
      scheduleSettingsCloudSave();
    });
    applyAccessibilityPrefs();

    document.getElementById('setEmotesRow').addEventListener('click', () => {
      emotesMuted = !emotesMuted;
      writePref('shithead_emotes_muted', emotesMuted);
      refreshSettingsUI();
      scheduleSettingsCloudSave();
    });

    // A "tap the ⓘ / ▦" tutorial step only counts the tap that OPENS the panel.
    function tutorialRefButtonTap(selector, isOpen, toggle) {
      const tutorialWantsIt = tutorialActive && TUTORIAL_STEPS[tutorialStep]?.require?.tapCheck === selector;
      if (tutorialWantsIt && isOpen()) return;
      toggle();
      if (tutorialWantsIt) tutorialOnTapCheck(selector);
    }
    document.getElementById('cardRefBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      tutorialRefButtonTap('#cardRefBtn', () => cardRefOpen, () => toggleCardReference());
    });
    initCardRefDrag();
    initCardRefZoomControls();
    document.getElementById('matrixRefBtn').addEventListener('click', (e) => {
      e.stopPropagation();
      tutorialRefButtonTap('#matrixRefBtn', () => matrixRefOpen, () => toggleMatrixReference());
    });
    initMatrixRefDrag();
    initMatrixRefZoomControls();
    initHistoryDragScroll();
    window.addEventListener('resize', () => positionCardRefPanel());
    window.addEventListener('resize', () => positionMatrixRefPanel());

    // Guards a button so it only fires on a genuine tap — a press that
    // STARTS on this element and is released without significant movement.
    // Without this, a touch that merely drifts across the screen and happens
    // to LIFT over a small, frequently-repositioned button still fires a
    // normal click in most mobile browsers, even though the person never
    // intended to press it. That's an easy accident on the tutorial's
    // Continue/Back/Skip buttons specifically, since they sit in the exact
    // same screen position on every step — a stray touch (adjusting grip on
    // the phone, a swipe that drifts) can "activate" whichever one is
    // sitting there, which looks indistinguishable from the tutorial
    // silently advancing on its own.
    function bindTapOnly(el, handler) {
      if (!el) return;
      const THRESHOLD = 12; // px of allowed movement to still count as a tap
      let startX = null, startY = null, trackingPointer = false;
      el.addEventListener('pointerdown', (e) => {
        startX = e.clientX; startY = e.clientY; trackingPointer = true;
      });
      el.addEventListener('click', (e) => {
        if (!trackingPointer) { handler(e); return; } // keyboard/synthetic activation — no drag to check
        trackingPointer = false;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.hypot(dx, dy) > THRESHOLD) return; // drag-release, not a real tap — ignore
        handler(e);
      });
    }

    // First time: straight into the one-minute Quick Start. After that the
    // button opens the hub (Quick Start is its first row).
    document.getElementById('startTutorialBtn').addEventListener('click', () => {
      if (getTutorialProgress()[QUICK_START_MODULE.id]) { openTutorialHub(); return; }
      launchTutorialModule(QUICK_START_MODULE.id, { fromHub: false });
    });
    document.getElementById('tutorialHubCloseBtn')?.addEventListener('click', () => closeTutorialHub());
    document.querySelectorAll('.tutorial-hub-section-header').forEach((header) => {
      header.addEventListener('click', () => {
        const section = header.dataset.section;
        const body = header.nextElementSibling;
        const currentlyCollapsed = body?.classList.contains('hidden');
        setTutorialHubCollapsePref(section, !currentlyCollapsed);
        renderTutorialHub();
      });
    });
    document.getElementById('tutorialHubResetBtn')?.addEventListener('click', (e) => {
      const btn = e.currentTarget;
      if (btn.dataset.confirming === '1') {
        try { localStorage.removeItem('shithead_tutorial_progress'); } catch (err) {}
        btn.dataset.confirming = '0';
        btn.textContent = 'Reset progress';
        btn.classList.remove('text-rose-400');
        renderTutorialHub();
        return;
      }
      btn.dataset.confirming = '1';
      btn.textContent = 'Tap again to confirm';
      btn.classList.add('text-rose-400');
      setTimeout(() => {
        if (btn.dataset.confirming === '1') {
          btn.dataset.confirming = '0';
          btn.textContent = 'Reset progress';
          btn.classList.remove('text-rose-400');
        }
      }, 3000);
    });
    bindTapOnly(document.getElementById('tutorialNextBtn'), () => {
      // Hidden = the Coach is mid-play (see below): a late or queued tap does nothing.
      if (document.getElementById('tutorialNextBtn').style.display === 'none') return;
      if (tutorialPendingContinueAction) {
        const fn = tutorialPendingContinueAction;
        tutorialPendingContinueAction = null;
        // Hidden while the Coach plays (about a second before anything
        // moves): a second tap here used to skip to the next step and cancel
        // the play, e.g. the 3 lesson's Coach 3 never landed. The note that
        // follows (showCoachNote / tutorialShowInterimNote) shows it again.
        document.getElementById('tutorialNextBtn').style.display = 'none';
        fn();
        return;
      }
      showTutorialStep(tutorialStep + 1);
    });
    bindTapOnly(document.getElementById('tutorialBackBtn'), () => {
      // Genuine undo: restore the board exactly as it was when the PREVIOUS
      // step began, so any card played, picked up or burnt is reversed.
      tutorialClearTimers();
      // Forget this step's snapshot so moving forward again replays it fresh.
      tutorialSnapshots[tutorialStep] = null;
      showTutorialStep(tutorialStep - 1);
    });
    bindTapOnly(document.getElementById('tutorialSkipBtn'), () => endTutorial(false));
    // tapCheck steps aren't a real game action, so they can't hook into any
    // existing per-element click handler — this single delegated listener
    // covers every step that uses one, whatever selector it names.
    document.addEventListener('click', (e) => {
      if (!tutorialActive) return;
      const step = TUTORIAL_STEPS[tutorialStep];
      const wantSel = step && step.require && step.require.tapCheck;
      if (!wantSel) return;
      if (e.target.closest(wantSel)) tutorialOnTapCheck(wantSel);
    });
    // Keep the spotlight aligned if the layout shifts (rotation, resize).
    window.addEventListener('resize', () => {
      if (tutorialActive) {
        const st = TUTORIAL_STEPS[tutorialStep];
        positionTutorialUI(st?.target);
      }
    });

    // Copies the room code so it can be pasted straight into WhatsApp etc.
    // navigator.clipboard only exists in secure contexts (https / localhost),
    // and this game is very often opened straight off the filesystem — so the
    // older execCommand path is a genuine necessity here, not just belt and
    // braces. If both fail, the code text itself is selectable as a last
    // resort.
    async function copyTextToClipboard(text) {
      try {
        if (navigator.clipboard && window.isSecureContext) {
          await navigator.clipboard.writeText(text);
          return true;
        }
      } catch (e) { /* fall through to the legacy path below */ }
      try {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.setAttribute('readonly', '');
        ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
        document.body.appendChild(ta);
        ta.select();
        ta.setSelectionRange(0, text.length); // iOS needs an explicit range
        const copied = document.execCommand('copy');
        ta.remove();
        return copied;
      } catch (e) { return false; }
    }
    function currentLobbyRoomCode() {
      const code = state.roomCode || document.getElementById('prominentRoomCode').textContent.trim();
      return /^[0-9]{6}$/.test(code || '') ? code : null;
    }
    document.getElementById('copyRoomCodeBtn').addEventListener('click', async () => {
      const code = currentLobbyRoomCode();
      if (!code) return;
      const copied = await copyTextToClipboard(code);

      const label = document.getElementById('copyRoomCodeLabel');
      const icon = document.getElementById('copyRoomCodeIcon');
      if (copied) {
        icon.textContent = '✅';
        label.textContent = 'Copied';
        Haptics.vibrate(20);
      } else {
        icon.textContent = '⚠️';
        label.textContent = 'Select it';
      }
      setTimeout(() => {
        icon.textContent = '📋';
        label.textContent = 'Copy';
      }, 1800);
    });

    // § Invite links: https://shithead-deluxe.web.app/?join=<code> opens the game
    // straight into that room (handleInviteLinkOnLoad). The lobby's Share
    // Invite Link button sends it through the phone's share sheet (WhatsApp
    // etc.), or copies it where sharing isn't available.
    const INVITE_LINK_BASE = 'https://shithead-deluxe.web.app/';
    function inviteLinkFor(code) { return `${INVITE_LINK_BASE}?join=${encodeURIComponent(code)}`; }
    async function shareInviteLink(code) {
      const url = inviteLinkFor(code);
      const text = `Play ShitHead with me! Tap to join my room (code ${code}):`;
      if (navigator.share) {
        try { await navigator.share({ title: 'ShitHead Deluxe', text, url }); return 'shared'; }
        catch (e) { if (e && e.name === 'AbortError') return 'cancelled'; }
      }
      return (await copyTextToClipboard(`${text} ${url}`)) ? 'copied' : 'failed';
    }
    document.getElementById('shareInviteLinkBtn').addEventListener('click', async () => {
      const code = currentLobbyRoomCode();
      if (!code) return;
      const result = await shareInviteLink(code);
      const label = document.getElementById('shareInviteLinkLabel');
      const icon = document.getElementById('shareInviteLinkIcon');
      if (result === 'copied') { icon.textContent = '✅'; label.textContent = 'Copied'; Haptics.vibrate(20); }
      else if (result === 'failed') { icon.textContent = '⚠️'; label.textContent = inviteLinkFor(code).replace('https://', ''); }
      else return;
      setTimeout(() => { icon.textContent = '🔗'; label.textContent = 'Share link'; }, result === 'failed' ? 6000 : 1800);
    });
    // Arriving from an invite link: wait for sign-in to settle (so the seat is
    // tied to the account), then open Online Room with the code filled in and
    // join, or ask for a nickname first. Never interrupts a match or rejoin.
    function inviteCodeFromUrl() {
      const code = new URLSearchParams(location.search).get('join');
      return /^[0-9]{6}$/.test(code || '') ? code : null;
    }
    function handleInviteLinkOnLoad() {
      const code = inviteCodeFromUrl();
      if (!code) return;
      const params = new URLSearchParams(location.search);
      params.delete('join');
      history.replaceState(history.state, '', location.pathname + (params.toString() ? `?${params}` : '') + location.hash);
      let attempt = 0;
      const tryJoin = () => {
        attempt++;
        // Sign-in first (the seat is tied to the account), then a beat for a
        // pending "Rejoin your match?" check and the account nickname.
        if (!authStateResolved && attempt < 16) { setTimeout(tryJoin, 250); return; }
        if (attempt < 100) { attempt = 100; setTimeout(tryJoin, 1200); return; }
        if (state.isMultiplayer || (state.phase && state.phase !== 'LOBBY')) return;
        if (!document.getElementById('rejoinModal')?.classList.contains('hidden')) return;
        if (isOffline()) { notifyBanner(OFFLINE_MODE_MSG); return; }
        document.getElementById('modeMultiBtn').click();
        document.getElementById('joinCodeInput').value = code;
        const nameInput = document.getElementById('playerNameInput');
        if (nameInput && nameInput.value.trim()) {
          notifyBanner(`🔗 Joining room ${code}…`);
          joinMultiRoom();
        } else {
          notifyBanner(`🔗 Enter a nickname, then tap JOIN to enter room ${code}.`);
          requireValidName();
        }
      };
      setTimeout(tryJoin, 600);
    }
    if (!IS_DEV_TEST_PAGE) handleInviteLinkOnLoad();
    if (!IS_DEV_TEST_PAGE) setTimeout(() => handleReferralLinkOnLoad(), 0); // defined further down

    (function wireEmoteButton() {
      const btn = document.getElementById('emoteToggleBtn');
      let hold = null, held = false;
      const cancel = () => { if (hold) { clearTimeout(hold.timer); hold = null; } };
      btn.addEventListener('pointerdown', (e) => {
        held = false;
        if (e.button > 0) return;
        hold = { x: e.clientX, y: e.clientY, timer: setTimeout(() => { hold = null; held = true; if (navigator.vibrate) try { navigator.vibrate(8); } catch (err) {} resendLastEmote(); }, CARD_HOLD_MS) };
      });
      btn.addEventListener('pointermove', (e) => { if (hold && Math.hypot(e.clientX - hold.x, e.clientY - hold.y) > 8) cancel(); });
      ['pointerup', 'pointercancel', 'pointerleave'].forEach(t => btn.addEventListener(t, cancel));
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (held) { held = false; return; } // the hold already sent it
        toggleEmoteFan();
      });
    })();
    // Tapping anywhere else dismisses the fan without sending anything.
    document.addEventListener('click', () => {
      if (emoteFanOpen) toggleEmoteFan(true);
    });
    document.getElementById('closeRulesBtn').addEventListener('click', () => document.getElementById('rulesModal').classList.add('hidden'));

    // Accordion Handlers
    document.querySelectorAll('.accordion-toggle').forEach(btn => {
      btn.addEventListener('click', () => {
        const content = btn.nextElementSibling;
        const chevron = btn.querySelector('.chevron');
        const isOpen = !content.classList.contains('hidden');

        if (isOpen) {
          content.classList.add('hidden');
          chevron.style.transform = 'rotate(0deg)';
        } else {
          content.classList.remove('hidden');
          chevron.style.transform = 'rotate(180deg)';
        }
      });
    });

    // Guide search: tags each section's individual entries once at load —
    // a <p> tag directly, or one level deeper for the two grid-based
    // sections (Card Powers, Keyboard Shortcuts) — so search can show/hide
    // individual entries rather than only whole sections. Plain substring
    // matching against each entry's own text, not a hand-written synonym
    // list like Settings has: with ~50 entries across 5 sections here,
    // the entries' own wording already covers most things someone would
    // search for, and every entry is fully visible up front rather than
    // starting collapsed like Settings' rows, unlike Settings' short toggle
    // labels which often don't contain the word someone would search for.
    document.querySelectorAll('#rulesModal .accordion-content').forEach((content) => {
      Array.from(content.children).forEach((child) => {
        if (child.classList.contains('grid')) {
          Array.from(child.children).forEach((gc) => gc.classList.add('guide-searchable'));
        } else {
          child.classList.add('guide-searchable');
        }
      });
    });
    document.getElementById('guideSearchInput').addEventListener('input', (e) => {
      const q = e.target.value.trim().toLowerCase();
      let anyVisible = false;
      document.querySelectorAll('#rulesModal .guide-searchable').forEach((item) => {
        const match = !q || item.textContent.toLowerCase().includes(q);
        item.classList.toggle('hidden', !match);
        if (match) anyVisible = true;
      });
      document.querySelectorAll('#rulesModal .accordion-toggle').forEach((toggle) => {
        const content = toggle.nextElementSibling;
        const chevron = toggle.querySelector('.chevron');
        if (!content) return;
        if (!q) {
          content.classList.add('hidden');
          if (chevron) chevron.style.transform = 'rotate(0deg)';
          return;
        }
        const hasMatch = Array.from(content.querySelectorAll('.guide-searchable')).some((el) => !el.classList.contains('hidden'));
        content.classList.toggle('hidden', !hasMatch);
        if (chevron) chevron.style.transform = hasMatch ? 'rotate(180deg)' : 'rotate(0deg)';
      });
      document.getElementById('guideNoResultsMsg').classList.toggle('hidden', anyVisible || !q);
    });

    // Wire lobby controls at their original startup position.
    initMultiplayerLobbyControls();

    document.getElementById('needHumanCloseBtn').addEventListener('click', () => {
      document.getElementById('needHumanModal').classList.add('hidden');
    });
    document.getElementById('needHumanCopyBtn').addEventListener('click', () => {
      const code = state.roomCode || '';
      if (code && navigator.clipboard) {
        navigator.clipboard.writeText(code).then(() => notifyBanner("Room code copied.")).catch(() => {});
      }
    });
    document.getElementById('needHumanBotsBtn').addEventListener('click', () => {
      document.getElementById('needHumanModal').classList.add('hidden');
      // Best-effort: remove ourselves from the online room, then return to the
      // home screen — "Play vs Bots" is already the default selected mode there,
      // so the player can review bot count/difficulty before starting themselves.
      if (state.roomCode) {
        const code = state.roomCode;
        const myId = state.localPlayerId;
        updatePlayersAtomic(code, (currentList) => currentList.filter(p => p.id !== myId), () => {
          forgetJoinedRoom();
          location.reload();
        });
      } else {
        forgetJoinedRoom();
        location.reload();
      }
    });

    async function leaveCurrentScreen({ toRoot = false } = {}) {
      if (state.spectating) { stopSpectating(); return; }
      if (!toRoot && document.body.matches('.lobby-open.mode-page') && document.getElementById('multiLobbyRoom')?.classList.contains('hidden') !== false) { document.getElementById('modePageBack').click(); return; }
      if (!toRoot && document.body.classList.contains('lobby-open')) { exitAppFromHome(); return; }
      if (tutorialActive) { document.getElementById('tutorialSkipBtn')?.click(); return; }
      const midMatch = state.phase === 'PLAY' || state.phase === 'SWAP';
      if (state.isMultiplayer && seriesActiveHere()) {
        seriesBeforeLeave().then((go) => {
          if (!go) return;
          if (midMatch) { Health.matchLeft(); Health.save(); weeklyStreakBroken(); }
          forgetJoinedRoom();
          if (toRoot) sessionStorage.removeItem('shithead_return_to_ranked');
          leaveMultiplayerRoom().then(reloadCleanly);
        });
        return;
      }
      const msg = midMatch && state.isRanked && state.isMultiplayer
        ? "A bot takes your seat and it counts as a loss: your rating will go down."
        : midMatch
          ? "Your progress in it will be lost and you can't rejoin."
          : "Return to the home screen.";
      if (await shConfirm({ title: midMatch ? 'Forfeit this match?' : 'Back to home?', text: msg, yes: midMatch ? 'Forfeit' : 'Go Home', no: 'Stay' })) {
        if (midMatch) { Health.matchLeft(); Health.save(); weeklyStreakBroken(); }
        forgetJoinedRoom();
        localStorage.removeItem('shithead_game_state');
        // Only a signed-in player should be returned to the Ranked lobby.
        // Guests always land on the normal home screen without an auth prompt.
        if (!toRoot && state.isRanked && currentUser) sessionStorage.setItem('shithead_return_to_ranked', '1');
        else sessionStorage.removeItem('shithead_return_to_ranked');
        leaveMultiplayerRoom().then(reloadCleanly);
      }
    }
    document.getElementById('leaveGameBtn').addEventListener('click', () => leaveCurrentScreen());

    // Any menu, modal, or text input currently open/focused — the single
    // check every card-specific gameplay shortcut (and now S) is gated
    // behind, so a background keystroke can never toggle "select all of
    // a rank" behind an open Settings panel, or play a card while the
    // player is typing into a room-code field. M and I are deliberately
    // NOT gated by this (see below) — they need to work precisely when
    // something IS open, to close it.
    const BLOCKING_OVERLAY_IDS = ['houseNameModal','friendsConfigModal','authModal', 'challengesModal', 'deleteAccountModal', 'friendsModal', 'inboxModal', 'leaderboardModal', 'matchStatsModal', 'needHumanModal', 'pileInspectModal', 'profileModal', 'rulesModal', 'settingsModal', 'shopModal', 'statsModal', 'supportModal', 'themesModal', 'usernameModal', 'errorReportsModal', 'changelogModal', 'rejoinModal', 'whatsNewModal'];
    // Every page and pop-up springs in as it opens, whatever opened it.
    (function watchOverlayEntrances() {
      const ids = [...BLOCKING_OVERLAY_IDS, 'tutorialHubScreen', 'matchSummaryModal', 'difficultyUnlockPopup'];
      ids.forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;
        let wasHidden = el.classList.contains('hidden');
        new MutationObserver(() => {
          const hidden = el.classList.contains('hidden');
          if (wasHidden && !hidden) springIn(el.firstElementChild);
          wasHidden = hidden;
        }).observe(el, { attributes: true, attributeFilter: ['class'] });
      });
    })();
    function isAnyOverlayOpen() {
      if (document.getElementById('hamburgerDrawer')?.classList.contains('open')) return true;
      return [...new Set([...BLOCKING_OVERLAY_IDS, ...MENU_PAGE_IDS])].some((id) => {
        const el = document.getElementById(id);
        return el && !el.classList.contains('hidden');
      });
    }
    function syncBackgroundScrollLock() {
      const tutorialHubOpen = !document.getElementById('tutorialHubScreen')?.classList.contains('hidden');
      document.body.classList.toggle('ui-overlay-open', isAnyOverlayOpen() || tutorialHubOpen);
    }
    const overlayScrollLockObserver = new MutationObserver(syncBackgroundScrollLock);
    [...new Set([...BLOCKING_OVERLAY_IDS, ...MENU_PAGE_IDS, 'tutorialHubScreen', 'hamburgerDrawer'])].forEach(id => {
      const element = document.getElementById(id);
      if (element) overlayScrollLockObserver.observe(element, { attributes:true, attributeFilter:['class'] });
    });
    syncBackgroundScrollLock();
    function isTypingInField() {
      const activeTag = document.activeElement && document.activeElement.tagName;
      return activeTag === 'INPUT' || activeTag === 'TEXTAREA' || document.activeElement?.isContentEditable;
    }

    // § Referrals: https://shithead-deluxe.web.app/?ref=<CODE>
    // The code is remembered from the link (localStorage) until the player is
    // signed in, then the server links the new account to the inviter (economy
    // referral 'claim': new accounts with a verified email only, once). The
    // server counts the new player's games and pays both (see functions/economy.js).
    const REF_PENDING_KEY = 'shithead_ref_code';
    const REF_PENDING_MAX_AGE = 30 * 864e5;
    // referralStatusCache (last economy referral 'status') is declared at the top of the script.
    const referralLinkFor = (code) => `https://shithead-deluxe.web.app/?ref=${encodeURIComponent(code)}`;
    function pendingReferral() {
      try {
        const p = JSON.parse(localStorage.getItem(REF_PENDING_KEY) || 'null');
        if (!p || !p.code || Date.now() - (p.at || 0) > REF_PENDING_MAX_AGE) return null;
        return p;
      } catch (e) { return null; }
    }
    function setPendingReferral(value) {
      try { if (value) localStorage.setItem(REF_PENDING_KEY, JSON.stringify(value)); else localStorage.removeItem(REF_PENDING_KEY); } catch (e) {}
    }
    function handleReferralLinkOnLoad() {
      const params = new URLSearchParams(location.search);
      const code = (params.get('ref') || '').toUpperCase();
      if (!params.has('ref')) return;
      params.delete('ref');
      history.replaceState(history.state, '', location.pathname + (params.toString() ? `?${params}` : '') + location.hash);
      if (!/^[A-Z0-9]{3,16}$/.test(code)) return;
      setPendingReferral({ code, at: Date.now() });
      let attempt = 0;
      const greet = () => {
        if (!authStateResolved && ++attempt < 20) { setTimeout(greet, 250); return; }
        if (currentUser) claimPendingReferral();
        else showReferralWelcome('invited');
      };
      setTimeout(greet, 1500);
    }
    let referralClaimInFlight = false;
    function claimPendingReferral() {
      const pending = pendingReferral();
      if (!pending || !currentUser || referralClaimInFlight || isOffline()) return Promise.resolve(null);
      referralClaimInFlight = true;
      return callEconomy('referral', { op: 'claim', code: pending.code }).then((res) => {
        setPendingReferral(null);
        referralStatusCache = res;
        showReferralWelcome('joined', res.inviterName);
        if (typeof renderFriendsList === 'function' && !document.getElementById('friendsModal')?.classList.contains('hidden')) renderFriendsList();
        return res;
      }).catch((e) => {
        // Final answers (already linked, not a new account, own code, bad code)
        // drop the code; anything else (no signal, email not verified yet) keeps it.
        if (/already linked|new accounts|own invite|not found|not valid/i.test(e.message)) setPendingReferral(null);
        if (/not found|not valid/i.test(e.message)) notifyBanner(`⚠️ ${e.message}`);
        return null;
      }).finally(() => { referralClaimInFlight = false; });
    }
    // The home screen hides the table's banners, so arriving by a link gets a
    // small pop-up: an invite to sign up, then "you joined" once linked.
    function showReferralWelcome(kind, inviterName, attempt = 0) {
      const modal = document.getElementById('referralWelcomeModal');
      // A new player is usually still choosing a username: wait for that
      // (and any other pop-up) to close, then show it.
      const busy = ['rejoinModal', 'authModal', 'usernameModal', 'gauntletModal'].some(id => !document.getElementById(id)?.classList.contains('hidden'));
      if (busy && attempt < 180) { setTimeout(() => showReferralWelcome(kind, inviterName, attempt + 1), 1000); return; }
      const joined = kind === 'joined';
      document.getElementById('referralWelcomeTitle').textContent = joined ? `You joined with ${inviterName || 'a friend'}'s invite!` : "You've been invited!";
      document.getElementById('referralWelcomeText').innerHTML = joined
        ? `You're friends now. Play <b>${REFERRAL.gamesNeeded} games</b> (any mode) and you get <b>💎 ${REFERRAL.newPlayerReward}</b>, and so do they.`
        : `A friend sent you their invite. Sign up and play <b>${REFERRAL.gamesNeeded} games</b> to get <b>💎 ${REFERRAL.newPlayerReward}</b>. You'll be made friends automatically.`;
      const go = document.getElementById('referralWelcomeGoBtn');
      go.textContent = joined ? "LET'S PLAY" : 'SIGN UP';
      go.dataset.kind = kind;
      modal.classList.remove('hidden');
    }
    document.getElementById('referralWelcomeGoBtn').addEventListener('click', (e) => {
      document.getElementById('referralWelcomeModal').classList.add('hidden');
      if (e.currentTarget.dataset.kind === 'invited') { openAuthModal(); setAuthMode('signup'); }
    });
    document.getElementById('referralWelcomeCloseBtn').addEventListener('click', () => document.getElementById('referralWelcomeModal').classList.add('hidden'));
    function fetchReferralStatus() {
      if (!currentUser || isOffline()) return Promise.resolve(referralStatusCache);
      return callEconomy('referral', { op: 'status' }).then((res) => { referralStatusCache = res; return res; })
        .catch(() => referralStatusCache);
    }
    function ensureReferralCode() {
      if (referralStatusCache && referralStatusCache.code) return Promise.resolve(referralStatusCache.code);
      return callEconomy('referral', { op: 'code' }).then((res) => { referralStatusCache = res; return res.code; });
    }
    async function shareReferralLink() {
      if (!currentUser) { openAuthModal(); notifyBanner('Sign in to get your own invite link.'); return 'signin'; }
      let code;
      try { code = await ensureReferralCode(); }
      catch (e) { notifyBanner(`⚠️ ${e.message}`); return 'failed'; }
      renderProfileReferral();
      const url = referralLinkFor(code);
      const text = `Play ShitHead with me! Sign up with my link and play ${REFERRAL.gamesNeeded} games: we both get Diamonds 💎`;
      if (navigator.share) {
        try { await navigator.share({ title: 'ShitHead Deluxe', text, url }); return 'shared'; }
        catch (e) { if (e && e.name === 'AbortError') return 'cancelled'; }
      }
      if (await copyTextToClipboard(`${text} ${url}`)) { notifyBanner('Invite link copied.'); Haptics.vibrate(20); return 'copied'; }
      notifyBanner(url.replace('https://', ''));
      return 'failed';
    }
    document.getElementById('friendsInviteBtn').addEventListener('click', () => shareReferralLink());

    // Profile → Invite Friends: your code and link, who joined and how far
    // along they are, your Recruiter progress, and who invited you.
    function referralProfileHtml(st) {
      if (!st) return '<p class="ref-how">Loading…</p>';
      const pips = (n) => `<span class="ref-pips" aria-label="${n} of ${REFERRAL.gamesNeeded} games">${Array.from({ length: REFERRAL.gamesNeeded }, (_, i) => `<i class="${i < n ? 'on' : ''}"></i>`).join('')}</span>`;
      const codeRow = st.code
        ? `<div class="ref-code-row"><div class="min-w-0" style="flex:1"><div class="ref-code">${escapeHtml(st.code)}</div><span class="ref-link">${escapeHtml(referralLinkFor(st.code).replace('https://', ''))}</span></div>
            <button type="button" class="ref-btn" data-ref-action="share">SHARE</button><button type="button" class="ref-btn" data-ref-action="copy">COPY</button></div>`
        : `<button type="button" class="ref-invite-btn" data-ref-action="share" style="margin:0"><span aria-hidden="true">🔗</span><span>GET MY INVITE LINK</span></button>`;
      const how = `<p class="ref-how">When a friend signs up with your link and plays <b>${REFERRAL.gamesNeeded} games</b>, you get <b>💎 ${REFERRAL.inviterReward}</b> and they get <b>💎 ${REFERRAL.newPlayerReward}</b>. You're made friends automatically. Recruit <b>${REFERRAL.recruiterTarget}</b> to earn the <b>${REFERRAL.pictureName}</b> avatar. Up to ${REFERRAL.monthlyCap} paid invites a month.</p>`;
      const stats = `<div class="ref-stat-row"><div class="ref-stat"><b>${Math.min(st.recruited || 0, REFERRAL.recruiterTarget)}/${REFERRAL.recruiterTarget}</b><span>Recruiter</span></div>
        <div class="ref-stat"><b>${(st.recruits || []).length}</b><span>Joined</span></div>
        <div class="ref-stat"><b>${st.paidThisMonth || 0}/${REFERRAL.monthlyCap}</b><span>Paid this month</span></div></div>`;
      const list = (st.recruits || []).length ? `<div class="ref-list">${st.recruits.map(r => `<div class="ref-person"><span class="ref-name">${escapeHtml(r.name)}</span>${pips(r.done ? REFERRAL.gamesNeeded : r.games)}<span class="ref-state">${r.done ? (r.reward ? `✓ +${r.reward} 💎` : '✓') : `${r.games}/${REFERRAL.gamesNeeded}`}</span></div>`).join('')}</div>` : '';
      const invited = st.referredBy ? `<div class="ref-invited">🎁 Invited by <b>${escapeHtml(st.referredBy.name || 'a friend')}</b>: ${st.referredBy.paid ? `done, you both got your Diamonds.` : `${st.referredBy.games}/${st.referredBy.needed} games played. Finish them for 💎 ${REFERRAL.newPlayerReward}.`}</div>` : '';
      return codeRow + how + stats + list + invited;
    }
    function renderProfileReferral(fetch = false) {
      const section = document.getElementById('profileReferralSection');
      const body = document.getElementById('profileReferralBody');
      if (!section || !body) return;
      section.classList.toggle('hidden', !currentUser);
      if (!currentUser) return;
      body.innerHTML = referralProfileHtml(referralStatusCache);
      if (fetch) fetchReferralStatus().then((st) => { if (st) body.innerHTML = referralProfileHtml(st); });
    }
    document.getElementById('profileReferralBody').addEventListener('click', async (e) => {
      const btn = e.target.closest('[data-ref-action]');
      if (!btn) return;
      if (btn.dataset.refAction === 'share') { shareReferralLink(); return; }
      const code = referralStatusCache && referralStatusCache.code;
      if (code && await copyTextToClipboard(referralLinkFor(code))) { btn.textContent = 'COPIED'; Haptics.vibrate(20); setTimeout(() => { btn.textContent = 'COPY'; }, 1600); }
    });
    // The new player's progress after each finished game (economy matchFinished).
    function noteReferralProgress(ref) {
      if (!ref) return;
      if (referralStatusCache && referralStatusCache.referredBy) Object.assign(referralStatusCache.referredBy, { games: ref.games, paid: !!ref.paid });
      if (ref.paid) enqueueChallengeToast("Friend's invite complete", REFERRAL.newPlayerReward, -1);
      else notifyBanner(`🎁 Invite progress: ${ref.games}/${REFERRAL.gamesNeeded} games. ${REFERRAL.gamesNeeded - ref.games} more for 💎 ${REFERRAL.newPlayerReward}!`);
    }

    // § Phone back gesture
    // --- Phone back gesture / back button ---------------------------------
    // Android's back gesture and back button (and a left-edge swipe in the
    // installed iPhone app, which has no back gesture of its own) step back
    // through the game instead of closing it: the top pop-up or page closes
    // first, then the menu; at a table it asks before leaving the match.
    // Only on the home screen with nothing open does Back leave the app.
    // It works through one "guard" history entry that exists whenever there
    // is something to go back from.
    const BACK_LAYERS = {
      welcomeTour: () => window.ShWelcomeTour?.skip(),
      houseNameModal: () => window.ShHousePresets?.close(),
      friendsConfigModal: () => window.ShFriendsLobby?.closeConfig(),
      appClosingScreen: 'returnFromClosingBtn',
      shConfirm: 'shConfirmNo',
      deleteAccountModal: () => clickFirstShown(['deleteStep2CancelBtn', 'deleteStep1CancelBtn']),
      giftOpenModal: 'giftOpenClose', giftModal: 'giftModalClose', installHelpModal: 'installHelpClose',
      dailyRewardModal: () => closeDailyReward(), playerPopup: 'playerPopupClose', matchSummaryModal: 'matchSummaryClose',
      authModal: 'authCloseBtn', usernameModal: null, difficultyUnlockPopup: 'difficultyUnlockPopupBtn',
      matchStatsModal: 'matchStatsCloseBtn', historyGameModal: 'historyGameCloseBtn', modeIntroModal: () => closeModeIntro(), noMercyModal: () => closeNoMercyChoice(), twosModal: () => closeTwosChoice(), decksModal: () => closeDecksChoice(), puzzlesModal: () => window.ShPuzzles?.close(), friendsModal: 'friendsCloseBtn', inboxModal: 'inboxCloseBtn',
      leaderboardModal: 'leaderboardCloseBtn', profileModal: 'profileCloseBtn', collectionModal: 'collectionCloseBtn', levelLadderModal: 'levelLadderCloseBtn', supportModal: 'supportCloseBtn', errorReportsModal: 'errorReportsCloseBtn', changelogModal: 'changelogCloseBtn',
      shopModal: 'shopCloseBtn', challengesModal: 'challengesCloseBtn', statsModal: 'statsCloseBtn',
      themesModal: 'themesCloseBtn', settingsModal: 'settingsCloseBtn', tutorialHubScreen: 'tutorialHubCloseBtn',
      seriesModal: 'seriesLaterBtn', needHumanModal: 'needHumanCloseBtn', rejoinModal: 'rejoinNoBtn', gauntletModal: 'gauntletCloseBtn', referralWelcomeModal: 'referralWelcomeCloseBtn', keepAccountModal: null, whatsNewModal: 'whatsNewCloseBtn', eventPopupModal: 'eventPopupLaterBtn', rulesModal: 'closeRulesBtn', pileInspectModal: 'closeInspectBtn',
      victoryOverlay: 'closeVictoryBtn', floatingJokerBar: null, bigPreview: () => closeBigPreview(),
      followUpToastBanner: () => resolveFollowUpPlay(false)
    };
    const isShownOnScreen = (el) => !!el && !el.classList.contains('hidden') && el.getClientRects().length > 0;
    function clickFirstShown(ids) {
      const button = ids.map(id => document.getElementById(id)).find(isShownOnScreen);
      if (button) button.click();
    }
    // The top-most open pop-up/page/menu, or null.
    function topBackLayer() {
      if (document.getElementById('hamburgerDrawer')?.classList.contains('open')) return { id: 'hamburgerDrawer', close: () => closeHamburgerMenu() };
      let top = null, topZ = -Infinity;
      Object.keys(BACK_LAYERS).forEach((id) => {
        const el = document.getElementById(id);
        if (!isShownOnScreen(el)) return;
        const z = parseInt(getComputedStyle(el).zIndex, 10) || 0;
        if (z >= topZ) { top = id; topZ = z; }
      });
      if (!top) return null;
      const how = BACK_LAYERS[top];
      if (how === null) return { id: top, close: () => {} }; // must be answered on screen: Back does nothing
      return { id: top, close: typeof how === 'function' ? how : () => document.getElementById(how)?.click() };
    }
    // What Back does when nothing is open on top, or null on the home screen.
    function screenBackAction() {
      if (tutorialActive && isShownOnScreen(document.getElementById('tutorialSkipBtn'))) return () => document.getElementById('tutorialSkipBtn').click();
      if (rankedSearchTimer || rankedHeartbeatTimer || rankedAssignmentRef) return () => cancelRankedSearch();
      if (!document.body.classList.contains('lobby-open') && isShownOnScreen(document.getElementById('leaveGameBtn'))) return () => document.getElementById('leaveGameBtn').click();
      if (state.isMultiplayer && state.roomCode && state.isRanked) return () => {}; // a Ranked match is about to start
      if (state.isMultiplayer && state.roomCode && state.phase === 'LOBBY') return () => { if (confirm('Leave this room?')) leaveRoomAndReload(); };
      if (document.body.classList.contains('lobby-open') && (document.getElementById('lobbyScreen')?.classList.contains('mode-page-open') || window.modeExpandRunning?.())) return () => document.getElementById('modePageBack').click();
      return null;
    }
    const wantsBackGuard = () => !!topBackLayer() || !!screenBackAction();
    const hasBackGuard = () => !!(history.state && history.state.shBackGuard);
    let ignoreNextPopstate = false;
    function syncBackGuard() {
      if (devTestSuiteRunning) return;
      const want = wantsBackGuard();
      if (want && !hasBackGuard()) {
        history.pushState({ shBackGuard: true }, '');
      } else if (!want && hasBackGuard()) {
        // Closed with an on-screen button: drop the guard so the next Back
        // leaves the app straight away instead of doing nothing.
        ignoreNextPopstate = true;
        history.back();
      }
    }
    function handleBack() {
      const layer = topBackLayer();
      // A page opened from another page goes back to it (page trail, v246).
      if (layer) { layer.close(); if (EXCLUSIVE_PAGE_IDS.includes(layer.id)) backToPreviousPage(layer.id); return; }
      const action = screenBackAction();
      if (action) action();
    }
    // Escape on PC (v248, owner): closes every open menu, page and pop-up in
    // one press, back to the home screen (or the table during a game). It
    // stops at anything that must be answered (BACK_LAYERS null) and never
    // touches in-game prompts (Bonus Draw, the Joker bar). In a text box
    // the first Escape just leaves the box.
    const ESCAPE_STOPS = new Set(['followUpToastBanner', 'floatingJokerBar']);
    function escapeToHome() {
      guideReturnTo = null;
      Object.keys(pageTrail).forEach(k => delete pageTrail[k]);
      let closed = 0;
      for (let i = 0; i < 16; i++) {
        const layer = topBackLayer();
        if (!layer || ESCAPE_STOPS.has(layer.id) || BACK_LAYERS[layer.id] === null) break;
        layer.close();
        closed++;
        const el = document.getElementById(layer.id);
        if (layer.id !== 'hamburgerDrawer' && el && isShownOnScreen(el)) break; // it didn't close
        if (layer.id === 'hamburgerDrawer' && document.getElementById('hamburgerDrawer')?.classList.contains('open')) break;
      }
      return closed;
    }
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape' || e.defaultPrevented) return;
      const t = e.target;
      if (t && (t.tagName === 'TEXTAREA' || (t.tagName === 'INPUT' && !/^(checkbox|radio|range|button)$/i.test(t.type)))) { t.blur(); return; }
      if (escapeToHome()) e.preventDefault();
    });
    window.addEventListener('popstate', () => {
      if (ignoreNextPopstate) { ignoreNextPopstate = false; return; }
      handleBack();
      setTimeout(syncBackGuard, 60); // still something open? arm Back again
    });
    // A reload keeps the current history entry; if that was a guard it's
    // just a normal entry now (a fresh one is added when needed).
    if (hasBackGuard()) history.replaceState(null, '');
    let backGuardSyncTimer = null;
    const scheduleBackGuardSync = () => { clearTimeout(backGuardSyncTimer); backGuardSyncTimer = setTimeout(syncBackGuard, 80); };
    const backGuardObserver = new MutationObserver(scheduleBackGuardSync);
    [...Object.keys(BACK_LAYERS), 'hamburgerDrawer', 'lobbyScreen', 'leaveGameBtn', 'tutorialSkipBtn', 'rankedSearching', 'multiLobbyRoom'].forEach((id) => {
      const el = document.getElementById(id);
      if (el) backGuardObserver.observe(el, { attributes: true, attributeFilter: ['class', 'style'] });
    });
    scheduleBackGuardSync();
    // Reloads that end a match or leave a room first step off the guard
    // entry, so the fresh page doesn't start on a leftover history entry.
    // Reload onto the newest build (sw.js is network-first for the page).
    // Once per target version per session, so a phone that still gets the
    // old page (no signal) can't loop.
    function updateToLatestVersion(message, targetVersion = 'latest') {
      if (typeof devTestSuiteRunning !== 'undefined' && devTestSuiteRunning) return;
      // Compatibility checks queue an update; they never interrupt or reload a match.
      if (/^v\d+$/.test(targetVersion)) showUpdatePrompt(targetVersion);
      else checkForNewVersion(true);
    }
    // Home backdrop, carousel and responsive panel observers: home-navigation.js.
    initHomePanelSizing();
    initHomeModeCarousel();
    initHomeScreenObservers();

    // "Desktop site" on a phone (Chrome's ⋮ menu, Safari's Request Desktop
    // Website) makes the browser ignore the page's phone viewport and lay it
    // out 980px wide, shrunk to fit: every card looks tiny. Zooming the page
    // back up isn't safe (positions of pop-ups, flights and the tutorial
    // spotlight come out scaled, and the tablet CSS still applies), so the
    // game says how to switch it off instead, drawn at a readable size.
    function isDesktopSiteOnPhone() {
      const touch = (navigator.maxTouchPoints || 0) > 0 || !!window.matchMedia?.('(pointer: coarse)').matches;
      const screenW = Math.min(screen.width || 0, screen.height || 0);
      return touch && screenW > 0 && screenW < 600 && window.innerWidth > screenW * 1.3;
    }
    function showDesktopSiteNote() {
      if (typeof devTestSuiteRunning !== 'undefined' && devTestSuiteRunning) return;
      try { if (sessionStorage.getItem('shithead_desktop_site_note')) return; } catch (e) {}
      if (!isDesktopSiteOnPhone() || document.getElementById('desktopSiteNote')) return;
      const k = window.innerWidth / Math.min(screen.width, screen.height);
      const note = document.createElement('div');
      note.id = 'desktopSiteNote';
      note.setAttribute('role', 'alert');
      note.style.setProperty('--dsk', String(k));
      note.innerHTML = '<b>Desktop Site is on</b><span>That makes the game tiny on a phone. Open your browser menu and switch off “Desktop site”.</span><button type="button">OK</button>';
      note.querySelector('button').addEventListener('click', () => {
        note.remove();
        try { sessionStorage.setItem('shithead_desktop_site_note', '1'); } catch (e) {}
      });
      document.body.appendChild(note);
    }
    setTimeout(showDesktopSiteNote, 600);

    // Sign-in shortcuts for guests: the menu's Sign In and the match
    // summary's "Sign in to earn Diamonds" button.
    document.getElementById('drawerSignInBtn')?.addEventListener('click', () => { closeHamburgerMenu(); openAuthModal(); });
    document.addEventListener('click', (e) => { if (e.target.closest?.('[data-ms-signin]')) openAuthModal(); });

    // § Update prompt: a phone or installed app still running an older build
    // (left open, or restored from the background) is told a new version is
    // ready. The live page's BUILD stamp is read with no cache; if it's newer
    // than ours, #updatePrompt offers Update now (refresh the service worker,
    // reload: a game in progress resumes) or Later (asks again in 30 min).
    const UPDATE_CHECK_MS = 15 * 60 * 1000;
    let lastUpdateCheck = 0, updatePromptSnoozeUntil = 0, updateNotifiedFor = '', pendingUpdateVersion = '';
    function updatePromptAllowed() {
      const lobby = document.getElementById('lobbyScreen');
      return !!lobby && !lobby.classList.contains('hidden') && state.phase === 'LOBBY' && !state.roomCode && !state.isMultiplayer && !state.spectating && !tutorialActive && !isAnyOverlayOpen() && document.getElementById('tutorialHubScreen').classList.contains('hidden');
    }
    function refreshUpdatePrompt() {
      if (!updatePromptAllowed()) { document.getElementById('updatePrompt')?.classList.add('hidden'); return; }
      if (pendingUpdateVersion) showUpdatePrompt(pendingUpdateVersion);
    }
    function newerBuildIn(html) {
      const m = String(html || '').match(/BUILD:\s*\d{4}-\d{2}-\d{2}-(v\d+)/);
      if (!m) return null;
      return gameVersionNumber(m[1]) > gameVersionNumber(getGameVersionLabel()) ? m[1] : null;
    }
    async function checkForNewVersion(force = false) {
      if (typeof devTestSuiteRunning !== 'undefined' && devTestSuiteRunning) return null;
      if (!/^https?:$/.test(location.protocol) || /[?&]dev-tests=1/.test(location.search)) return null;
      if (!force && Date.now() - lastUpdateCheck < 5 * 60 * 1000) return null;
      lastUpdateCheck = Date.now();
      try {
        const r = await fetch(`/?v=${Date.now()}`, { cache: 'no-store' });
        if (!r.ok) return null;
        const newer = newerBuildIn(await r.text());
        if (newer) showUpdatePrompt(newer);
        return newer;
      } catch (e) { return null; }
    }
    function showUpdatePrompt(version) {
      pendingUpdateVersion = version;
      if (!updatePromptAllowed()) { document.getElementById('updatePrompt')?.classList.add('hidden'); return; }
      if (Date.now() < updatePromptSnoozeUntil && updateNotifiedFor === version) return;
      updateNotifiedFor = version;
      let el = document.getElementById('updatePrompt');
      if (!el) {
        el = document.createElement('div');
        el.id = 'updatePrompt';
        el.setAttribute('role', 'alertdialog');
        el.setAttribute('aria-live', 'polite');
        document.body.appendChild(el);
      }
      el.innerHTML = `<div class="up-row"><span class="up-icon">${icon('refresh')}</span><div class="up-text"><b>Update available</b><span>A new version (${escapeHtml(version)}) is ready.</span></div></div>
        <div class="up-btns"><button type="button" class="up-later">Later</button><button type="button" class="up-now">Update Now</button></div>`;
      el.classList.remove('hidden');
      el.querySelector('.up-later').onclick = () => { updatePromptSnoozeUntil = Date.now() + 30 * 60 * 1000; el.classList.add('hidden'); };
      el.querySelector('.up-now').onclick = () => applyUpdateNow();
    }
    async function applyUpdateNow() {
      if (!updatePromptAllowed()) { refreshUpdatePrompt(); return; }
      const el = document.getElementById('updatePrompt');
      if (el) el.querySelector('.up-now').textContent = 'Updating…';
      try { if (typeof saveGameState === 'function' && !state.isMultiplayer) saveGameState(); } catch (e) {}
      try {
        const reg = await navigator.serviceWorker?.getRegistration?.();
        await reg?.update?.();
      } catch (e) {}
      if (updatePromptAllowed()) reloadCleanly();
      else refreshUpdatePrompt();
    }
    const updateHomeObserver = new MutationObserver(refreshUpdatePrompt);
    ['lobbyScreen', 'tutorialHubScreen', ...BLOCKING_OVERLAY_IDS].forEach(id => {
      const el = document.getElementById(id);
      if (el) updateHomeObserver.observe(el, { attributes: true, attributeFilter: ['class'] });
    });
    setTimeout(() => checkForNewVersion(true), 15000);
    setInterval(() => checkForNewVersion(true), UPDATE_CHECK_MS);
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') checkForNewVersion(); });
    window.addEventListener('online', () => checkForNewVersion());
    function reloadCleanly() {
      // Back to the home screen at once: the boot splash is for cold starts only.
      try { sessionStorage.setItem('shithead_skip_splash', '1'); } catch (e) {}
      if (!hasBackGuard()) { location.reload(); return; }
      ignoreNextPopstate = true;
      window.addEventListener('popstate', () => location.reload(), { once: true });
      history.back();
      setTimeout(() => location.reload(), 500);
    }
    // Vs Bots only (the Leave button under "MATCH FINISHED"): back to the
    // home screen without restoring this game.
    function finishedLeaveOffered() {
      if (tutorialActive || state.spectating) return false;
      if (!state.isMultiplayer) return true;
      if (state.phase !== 'FINISHED') return false;
      try { return !seriesLiveHere(); } catch (e) { return true; }
    }
    function leaveFinishedMatch() {
      if (!state.isMultiplayer) { leaveBotMatch(); return; }
      if (!finishedLeaveOffered()) return;
      try { sessionStorage.removeItem('shithead_return_to_ranked'); } catch (e) {}
      leaveRoomAndReload();
    }
    function leaveBotMatch() {
      if (state.isMultiplayer) return;
      try { localStorage.removeItem('shithead_game_state'); } catch (e) {}
      try { sessionStorage.removeItem('shithead_return_to_ranked'); } catch (e) {}
      reloadCleanly();
    }
    async function leaveRoomAndReload() {
      if (!(await seriesBeforeLeave())) return;
      forgetJoinedRoom();
      leaveMultiplayerRoom().then(reloadCleanly);
    }
    // Installed iPhone app: swipe in from the left edge = Back.
    if (isIOSDevice() && isStandaloneApp()) {
      let edgeStart = null;
      document.addEventListener('touchstart', (e) => {
        const t = e.touches[0];
        edgeStart = (e.touches.length === 1 && t.clientX <= 24) ? { x: t.clientX, y: t.clientY, at: Date.now() } : null;
      }, { passive: true });
      document.addEventListener('touchend', (e) => {
        if (!edgeStart) return;
        const t = e.changedTouches[0];
        const dx = t.clientX - edgeStart.x, dy = Math.abs(t.clientY - edgeStart.y);
        const quick = Date.now() - edgeStart.at < 800;
        edgeStart = null;
        if (dx > 70 && dy < 60 && quick && hasBackGuard()) history.back();
      }, { passive: true });
    }

    // Keyboard Shortcuts
    window.addEventListener('keydown', (e) => {
      // 'M' toggles the hamburger menu, 'I' toggles the Inbox — both work
      // regardless of what else is currently open (including each
      // other), the same way Escape already closes the menu, so a
      // keyboard-only player always has a way in and a way back out.
      // Never active while typing into a text field.
      if (!isTypingInField() && !e.ctrlKey && !e.metaKey && !e.altKey) {
        if (e.key.toLowerCase() === 'm') {
          e.preventDefault();
          if (document.getElementById('hamburgerDrawer').classList.contains('open')) closeHamburgerMenu();
          else openHamburgerMenu();
          return;
        }
        if (e.key.toLowerCase() === 'i') {
          e.preventDefault();
          const inboxModal = document.getElementById('inboxModal');
          if (inboxModal.classList.contains('hidden')) openInboxPanel();
          else inboxModal.classList.add('hidden');
          return;
        }
      }
      // 'F' toggles fullscreen via the same Fullscreen API path as the
      // Settings row, so the state stays in sync regardless of which one
      // was used. F11 is deliberately NOT handled here — it's the
      // browser's own native fullscreen shortcut already, and browsers
      // generally don't let a page override or preventDefault it anyway,
      // so there's nothing for this code to add there. Deliberately NOT
      // gated by isAnyOverlayOpen() below — toggling fullscreen while a
      // menu or modal is open is harmless, and often exactly when a
      // player wants it (e.g. from Settings itself).
      if (e.key.toLowerCase() === 'f' && !e.ctrlKey && !e.metaKey && !e.altKey) {
        if (!isTypingInField()) {
          e.preventDefault();
          toggleFullscreen();
        }
        return;
      }
      // Safeguard: everything below this point is either 'S' or a card-
      // specific gameplay shortcut (2-9, J, Q, K, A, Space, Enter, 1/2/3)
      // — all of them go silent the instant any menu, modal, or text
      // field is active.
      if (isTypingInField() || isAnyOverlayOpen()) return;

      // 'S' toggles "select all of a rank" — independent of whose turn it
      // is or even the current phase, since the button itself (and its
      // click handler) has no such restriction either; it's a standing
      // preference, not a game action. Still guarded against modifier
      // combos (Ctrl/Cmd+S is "Save Page" in every browser).
      if (e.key.toLowerCase() === 's' && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        document.getElementById('multiSelectToggleBtn')?.click();
        return;
      }
      if (state.phase !== 'PLAY') return;
      const local = state.players.find(p => p.id === state.localPlayerId);
      const current = state.players[state.currentTurnIndex];
      if (!local || !current || current.id !== local.id || local.hasFinished) return;

      // Bonus Draw open: its card's key (or Enter) takes it, Escape skips it
      // (the back layer), every other card key is ignored (v288).
      const followUp = state.pendingFollowUp;
      if (followUp && followUp.playerId === local.id) {
        const bonus = (local.hand || []).find(c => c.id === followUp.cardId);
        const k = e.key.toUpperCase();
        const keyRank = k === '1' ? '10' : k;
        if (bonus && (k === 'ENTER' || keyRank === bonus.rank)) {
          e.preventDefault();
          state.selectedPlayCardIds = [];
          resolveFollowUpPlay(true);
        }
        return;
      }

      const hasHand = local.hand && local.hand.length > 0;
      const hasFaceUp = local.faceUp && local.faceUp.length > 0;
      const hasFaceDown = local.faceDown && local.faceDown.length > 0;

      // 1 / 2 / 3 address your TABLE cards by physical slot position (not
      // "the Nth card still remaining"), so they line up with what's on
      // screen even when a slot has been emptied.
      if (['1', '2', '3'].includes(e.key)) {
        const idx = parseInt(e.key) - 1;

        // Blind phase: face-down cards play instantly — there's nothing to
        // deliberate over, since you can't see them.
        if (canAccessFaceDown(local) && hasFaceDown) {
          const blindCardAtSlot = buildFixedSlots(local.faceDown)[idx];
          if (blindCardAtSlot) {
            if (tutorialActive && !tutorialAllowBlindPlay(idx)) return;
            tutorialPlayBlindCard(local.id, blindCardAtSlot);
            return;
          }
        }

        // Face-up phase: select the card in that slot (ENTER then plays it),
        // matching how tapping works. Gated by exactly the same access rule
        // as tapping, so the hierarchy can't be bypassed via the keyboard.
        if (canAccessFaceUp(local) && hasFaceUp) {
          const faceUpAtSlot = buildFixedSlots(local.faceUp)[idx];
          if (faceUpAtSlot) {
            toggleCardSelection(faceUpAtSlot.id, getAllSelectablePool(local));
            return;
          }
        }
      }

      const pool = getAllSelectablePool(local);
      if (!pool || pool.length === 0) return;

      const key = e.key.toUpperCase();
      let targetRank = null;
      let selectOnlyOne = false;

      if (['2', '3', '4', '5', '6', '7', '8', '9'].includes(key)) {
        targetRank = key;
      } else if (key === '1') {
        targetRank = '10';
      } else if (['J', 'Q', 'K', 'A'].includes(key)) {
        targetRank = key;
      } else if (e.key === ' ' || e.code === 'Space') {
        e.preventDefault(); // stop the page from scrolling on Space
        targetRank = 'JOKER';
        selectOnlyOne = true;
      } else if (key === 'ENTER') {
        if (state.selectedPlayCardIds.length > 0) {
          const cards = pool.filter(c => state.selectedPlayCardIds.includes(c.id));
          state.selectedPlayCardIds = [];
          executePlayCards(local.id, cards);
        }
        return;
      }

      if (targetRank) {
        const matching = pool.filter(c => c.rank === targetRank);
        if (matching.length > 0 && isPlayLegal(matching[0], state.discardPile, state.activeConstraint)) {
          // Default is a single card — the toggle is what opts into grabbing
          // the whole rank, matching how tapping behaves.
          const takeAll = selectAllOfRank && !selectOnlyOne && !bestCardIsProtected(targetRank);
          state.selectedPlayCardIds = takeAll ? matching.map(c => c.id) : [matching[0].id];
          render();
        }
      }
    });

    // =====================================================================
    // NAME REQUIRED
    // A name is required before starting or joining any match — important
    // for multiplayer, where an empty/placeholder name would be confusing for
    // everyone else at the table. Kept gentle: no blocking dialog, just an
    // inline message, a red border, and a brief shake to draw the eye.
    // =====================================================================
    function requireValidName() {
      const input = document.getElementById('playerNameInput');
      const msg = document.getElementById('nameRequiredMsg');
      if (!input) return true;
      if (input.value.trim()) {
        if (msg) msg.classList.add('hidden');
        input.classList.remove('border-rose-500');
        return true;
      }
      if (msg) msg.classList.remove('hidden');
      input.classList.add('border-rose-500');
      input.focus();
      input.classList.add('animate-screen-shake');
      setTimeout(() => input.classList.remove('animate-screen-shake'), 400);
      return false;
    }

    document.getElementById('playerNameInput').addEventListener('input', (e) => {
      if (e.target.value.trim()) {
        document.getElementById('nameRequiredMsg').classList.add('hidden');
        e.target.classList.remove('border-rose-500');
      }
    });

    // Session Restore
    // ============================================================
    // INTERACTIVE TUTORIAL — scripted, hands-on lesson.
    //
    // Design: each step is a SCENARIO. The tutorial sets up an exact board
    // (your hand, the Coach's hand, the pile), tells you precisely which card
    // to play, and refuses anything else with a helpful correction. After you
    // play, the Coach responds on a visible delay so you can actually watch
    // what happened. That makes it a lesson rather than a slideshow.
    //
    // Undo is genuine: a deep snapshot of game state is taken when each step
    // begins, and Back restores it wholesale — so any card played, picked up
    // or burnt during that step is properly reversed.
    //
    // Isolation: everything here is gated on tutorialActive. The only touch
    // points in game code are two one-line guards (bot pause + play intercept),
    // both of which short-circuit to normal behaviour when the tutorial is off.
    // ============================================================
    // Tutorial runtime is loaded from tutorial.js.
    // The developer test suite lives in dev-tests.js and is only fetched
    // when the page is opened with ?dev-tests=1.
    function loadDevTestSuite() {
      return new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = `dev-tests.js?v=${Date.now()}`;
        script.onload = resolve;
        script.onerror = () => reject(new Error('Could not load dev-tests.js'));
        document.head.appendChild(script);
      });
    }

    // § Page start-up
    window.addEventListener('DOMContentLoaded', () => {
      if (new URLSearchParams(location.search).get('dev-tests') === '1') {
        // Fire-and-forget is fine here — runDevTestSuite's own test()
        // wrapper catches every individual test failure internally, so
        // this only rejects on a genuine bug in the harness itself
        // (e.g. renderDevTestReport throwing) rather than a normal test
        // failure. Still caught, not left as a silent unhandled rejection.
        savedGameChecked = true; // no game to restore on the test page
        loadDevTestSuite().then(() => runDevTestSuite()).catch((e) => console.error('Dev test suite crashed', e));
        return;
      }
      ensureMpTimerUiLoop();

      const savedName = localStorage.getItem('shithead_player_name');
      const nameInput = document.getElementById('playerNameInput');
      if (savedName && nameInput) nameInput.value = savedName;

      // Apply persistent preferences even when there is no interrupted match
      // to restore. Previously theme/speed only repainted on the restore path,
      // making a saved choice appear forgotten on a fresh visit.
      setBodyDeckTheme(state.deckTheme);
      applyAccessibilityPrefs();
      updateSpeedByIndex(state.speedIndex ?? DEFAULT_SPEED_INDEX);

      const restored = loadGameState();
      savedGameChecked = true;
      if (restored && state.phase !== 'LOBBY') {
        setBodyDeckTheme(state.deckTheme);
        applyAccessibilityPrefs(); // className was just fully replaced above, which wipes high-contrast/reduce-motion -- reapply them
        dismissLobbyAndStart();
        updateSpeedByIndex(state.speedIndex ?? DEFAULT_SPEED_INDEX);

        if (state.phase === 'SWAP') {
          document.getElementById('swapControlBar').classList.remove('hidden');
          document.getElementById('playActionControls').classList.add('hidden');
        } else {
          document.getElementById('swapControlBar').classList.add('hidden');
          document.getElementById('playActionControls').classList.remove('hidden');
        }
        render();
        notifyBanner(state.gauntlet && !state.isMultiplayer
          ? `⚔️ ${gauntletTitle(gauntletModeOf(state.gauntlet)).replace(/^The /, '')} restored: round ${state.gauntlet.round + 1} of ${gauntletRounds(gauntletModeOf(state.gauntlet)).length}, right where you left it.`
          : "Game restored from previous session!");
        if (state.phase === 'PLAY' && !state.isMultiplayer) {
          triggerNextTurn();
        }
      } else {
        resumeGauntletBetweenGames();
      }
      refreshGauntletLobbyBtn();
    });
  